import { useCallback, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";
import "../css/Mybooking.css";

const API_BASE_URL = "http://localhost:5001";

function getStoredUser() {
  try {
    return JSON.parse(localStorage.getItem("user") || "null");
  } catch (error) {
    console.error("Unable to read user data:", error);
    return null;
  }
}

function formatDisplayDate(value) {
  if (!value) return "-";
  const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return match ? `${match[3]}/${match[2]}/${match[1]}` : String(value);
}

function BookingInfo({ label, value }) {
  return <p><strong>{label} </strong>{String(value ?? "-")}</p>;
}

function Mybooking() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadBookings = useCallback(async (currentUser) => {
    if (!currentUser?.user_id) {
      setError("ไม่พบข้อมูลบัญชีผู้ใช้ กรุณาเข้าสู่ระบบใหม่");
      setBookings([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(currentUser.user_id)}`
      );
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      setBookings(Array.isArray(data.bookings) ? data.bookings : []);
    } catch (requestError) {
      console.error("Unable to load bookings:", requestError);
      setError("โหลดรายการจองไม่ได้ กรุณาตรวจสอบว่า backend กำลังทำงานอยู่");
      setBookings([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const storedUser = getStoredUser();
    if (!storedUser) {
      navigate("/", { replace: true });
      return;
    }
    setUser(storedUser);
    loadBookings(storedUser);
  }, [loadBookings, navigate]);

  function logout() {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/", { replace: true });
  }

  async function cancelBooking(bookingId) {
    if (bookingId == null || !window.confirm("ยืนยันยกเลิกการจองนี้หรือไม่?")) return;

    try {
      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(bookingId)}`,
        {
          method: "DELETE",
          headers: { "X-User-Id": String(user?.user_id || "") }
        }
      );
      const result = await response.json();
      if (!response.ok || !result.success) {
        throw new Error(result.message || "ยกเลิกการจองไม่สำเร็จ");
      }
      await loadBookings(user);
    } catch (requestError) {
      console.error("Unable to cancel booking:", requestError);
      window.alert(requestError.message || "ยกเลิกการจองไม่สำเร็จ");
    }
  }

  if (!user) return <main className="homepage"><p>กำลังโหลด...</p></main>;

  return (
    <div className="homepage">
      <header className="topbar">
        <nav className="nav-menu">
          <span className="nav-home" title="HOME" onClick={() => navigate("/homepage")}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M3 11.5L12 4L21 11.5" stroke="#ffffff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              <path d="M5.5 10V19.5C5.5 20.0523 5.94772 20.5 6.5 20.5H9.5C10.0523 20.5 10.5 20.0523 10.5 19.5V15C10.5 14.4477 10.9477 14 11.5 14H12.5C13.0523 14 13.5 14.4477 13.5 15V19.5C13.5 20.0523 13.9477 20.5 14.5 20.5H17.5C18.0523 20.5 18.5 20.0523 18.5 19.5V10" stroke="#ffffff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </span>
          <span onClick={() => navigate("/mybooking")}>MY BOOKING</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/Guide.html`; }}>GUIDE</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/Rule.html`; }}>RULE</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/review.html`; }}>REVIEW</span>
        </nav>
        <div className="nav-right">
          <div className="profile-menu">
            <button type="button" id="profileBtn" className="profile-btn" aria-expanded={profileOpen} aria-controls="profilePopup" onClick={() => setProfileOpen(open => !open)}>
              <span>PROFILE</span>
              <span className="chevron" aria-hidden="true">⌄</span>
            </button>
          {profileOpen && (
            <div className="profile-popup">
              <section className="profile-card" role="region" aria-labelledby="profileTitle">
                <header className="profile-header">
                  <h3 id="profileTitle">PROFILE</h3>
                  <button id="closeProfileBtn" type="button" aria-label="ปิดโปรไฟล์" onClick={() => setProfileOpen(false)}>&times;</button>
                </header>
                <div className="profile-info">
                  <p><strong>Name:</strong> <span>{user.displayname_th || user.displayname_en || user.name || ""}</span></p>
                  <p><strong>Username:</strong> <span>{user.username || ""}</span></p>
                  <p><strong>Faculty:</strong> <span>{user.faculty || ""}</span></p>
                  <p><strong>Department:</strong> <span>{user.department || user.major || ""}</span></p>
                  <p><strong>Email:</strong> <span>{user.email || ""}</span></p>
                </div>
                <button id="logoutBtn" className="logout-btn" type="button" onClick={logout}>LOGOUT</button>
              </section>
            </div>
          )}
          </div>
        </div>
      </header>

      <section className="hero-section">
        <div className="logo-wrapper"><img src={`${process.env.PUBLIC_URL}/logo.png`} alt="Booking CSTU Room" className="hero-image-logo" /></div>
        <div className="hero-line" />
        <div className="hero-right"><h1>BOOKING<br />CSTU ROOM</h1></div>
      </section>

      <main className="main-content">
        <section className="content-wrapper mybooking-container">
          <div className="mybooking-heading">
  <div>
    <p className="mybooking-eyebrow">BOOKING CSTU ROOM</p>
    <h1>Your Bookings</h1>
    <p>ตรวจสอบรายการจองห้องประชุมของคุณ</p>
  </div>
</div>
          {loading ? <div className="no-bookings" role="status">กำลังโหลดรายการจอง...</div> : null}
          {!loading && error ? <div className="no-bookings" role="alert">{error}</div> : null}
          {!loading && !error && bookings.length === 0 ? <div className="no-bookings" role="status">ยังไม่มีรายการจอง</div> : null}
          {!loading && !error && bookings.length > 0 ? (
            <div id="bookingsContainer">
              {bookings.map(booking => (
                <article className="booking-card" key={booking.id}>
                  <h3>{booking.room_name || booking.room || "จองห้อง"}</h3>
                  <div className="booking-info">
                    <div>
                      <BookingInfo label="วันที่:" value={formatDisplayDate(booking.booking_date || booking.date)} />
                      <BookingInfo label="เวลา:" value={`${booking.start_time || "-"} - ${booking.end_time || "-"}`} />
                    </div>
                    <div>
                      <BookingInfo label="สถานะ:" value={booking.status || "รอดำเนินการ"} />
                      <BookingInfo label="หมายเลขการจอง:" value={booking.id} />
                    </div>
                  </div>
                  <div className="booking-card-actions">
                    <button type="button" className="cancel-btn" onClick={() => cancelBooking(booking.id)}>ยกเลิกการจอง</button>
                  </div>
                </article>
              ))}
            </div>
          ) : null}
        </section>
      </main>
    </div>
  );
}

export default Mybooking;
